create table public.store_addresses (id uuid primary key default gen_random_uuid(), store_id uuid not null references public.stores(id) on delete cascade, label text not null, address_line1 text not null, address_line2 text, locality text not null, city text not null, region text not null, postal_code text not null, country_code char(2) not null default 'IN', phone text, is_default boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create unique index uq_store_default_address on public.store_addresses(store_id) where is_default;
